function ApplyPollNewConditional() {
    var div = document.getElementById('divPollNew');
    if (!div)
        return;
    var selected = {};
    var radios = div.getElementsByTagName('input');
    var ri;
    for (ri = 0; ri < radios.length; ri++) {
        if (radios[ri].type != 'radio' || !radios[ri].checked)
            continue;
        var qcode = radios[ri].getAttribute('data-poll-qcode');
        var aindex = radios[ri].getAttribute('data-poll-aindex');
        if (qcode)
            selected[qcode] = aindex;
    }
    var blocks = div.getElementsByClassName('poll-question-block');
    var bi;
    for (bi = 0; bi < blocks.length; bi++) {
        var block = blocks[bi];
        if (block.getAttribute('data-is-conditional') != '1') {
            block.style.display = 'block';
            continue;
        }
        var expr = block.getAttribute('data-condition-expr');
        if (!expr || expr.indexOf('=') < 0) {
            block.style.display = 'none';
            continue;
        }
        var parts = expr.split('=');
        var triggerCode = PollNewTrim(parts[0]);
        var needIndex = PollNewTrim(parts[1]);
        if (selected[triggerCode] == needIndex)
            block.style.display = 'block';
        else
            block.style.display = 'none';
    }
}

